CREATE OR REPLACE FUNCTION public.register_as_developer(_display_name text DEFAULT NULL::text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _uid uuid:=auth.uid(); _name text; _phone text; _email text; _lead_id uuid; _warn text; BEGIN IF _uid IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF; PERFORM public.ensure_profile_row(_uid); IF NULLIF(btrim(_display_name),'') IS NOT NULL THEN UPDATE public.profiles SET full_name=COALESCE(NULLIF(btrim(full_name),''),btrim(_display_name)) WHERE id=_uid; END IF; INSERT INTO public.user_roles(user_id,role) VALUES (_uid,'developer') ON CONFLICT(user_id,role) DO NOTHING; UPDATE public.workspace_memberships SET account_type='developer' WHERE user_id=_uid AND workspace_owner_id=_uid; SELECT full_name,phone,email INTO _name,_phone,_email FROM public.profiles WHERE id=_uid; IF NULLIF(regexp_replace(COALESCE(_phone,''),'\D','','g'),'') IS NOT NULL THEN BEGIN _lead_id:=public.ensure_rita_crm_contact(_name,_phone,_email,'הרשמת יזם לאפליקציה','app_registration',_uid); EXCEPTION WHEN OTHERS THEN _warn:=SQLERRM; END; ELSE _warn:='registration_phone_missing'; END IF; RETURN jsonb_build_object('ok',true,'role','developer','user_id',_uid,'lead_id',_lead_id,'warning',_warn); END $$; REVOKE ALL ON FUNCTION public.register_as_developer(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.register_as_developer(text) TO authenticated,service_role;